SELECT CASE WHEN observed_at BETWEEN '2026-10-11 21:00:01.100' AND '2026-10-11 21:00:09.000' THEN 'G137' WHEN observed_at BETWEEN '2026-10-11 22:43:27.100' AND '2026-10-11 22:43:35.000' THEN 'G143' WHEN observed_at BETWEEN '2026-10-12 10:05:02.500' AND '2026-10-12 10:05:18.400' THEN 'G182' END AS gap_window, symbol, delivery_status, COUNT(*) AS n, MIN(observed_at) AS first_obs, MAX(observed_at) AS last_obs, MAX(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at))/1000 AS max_lag_ms FROM market_price_event WHERE (observed_at BETWEEN '2026-10-11 21:00:01.100' AND '2026-10-11 21:00:09.000') OR (observed_at BETWEEN '2026-10-11 22:43:27.100' AND '2026-10-11 22:43:35.000') OR (observed_at BETWEEN '2026-10-12 10:05:02.500' AND '2026-10-12 10:05:18.400') GROUP BY gap_window, symbol, delivery_status ORDER BY gap_window, symbol LIMIT 300